const fs = require('fs');
const path = require('path');

// OBJ Export Utilities
function geometryToOBJ(geometry) {
    const positions = geometry.attributes.position;
    const normals = geometry.attributes.normal;
    const indices = geometry.index;

    let vertices = [];
    let objLines = [];

    for (let i = 0; i < positions.count; i++) {
        objLines.push(`v ${positions.getX(i).toFixed(6)} ${positions.getY(i).toFixed(6)} ${positions.getZ(i).toFixed(6)}`);
    }

    if (normals) {
        for (let i = 0; i < normals.count; i++) {
            objLines.push(`vn ${normals.getX(i).toFixed(6)} ${normals.getY(i).toFixed(6)} ${normals.getZ(i).toFixed(6)}`);
        }
    }

    if (indices) {
        for (let i = 0; i < indices.count; i += 3) {
            const a = indices.getX(i) + 1;
            const b = indices.getX(i + 1) + 1;
            const c = indices.getX(i + 2) + 1;
            if (normals) {
                objLines.push(`f ${a}//${a} ${b}//${b} ${c}//${c}`);
            } else {
                objLines.push(`f ${a} ${b} ${c}`);
            }
        }
    } else {
        const count = positions.count;
        for (let i = 0; i < count; i += 3) {
            const a = i + 1;
            const b = i + 2;
            const c = i + 3;
            if (normals) {
                objLines.push(`f ${a}//${a} ${b}//${b} ${c}//${c}`);
            } else {
                objLines.push(`f ${a} ${b} ${c}`);
            }
        }
    }

    return objLines.join('\n');
}

