function createBufferGeometry(positions, normals, indices) {
    const posArray = new Float32Array(positions);
    const normArray = new Float32Array(normals);
    const idxArray = new Uint16Array(indices);

    return {
        attributes: {
            position: {
                count: posArray.length / 3,
                getX: (i) => posArray[i * 3],
                getY: (i) => posArray[i * 3 + 1],
                getZ: (i) => posArray[i * 3 + 2]
            },
            normal: {
                count: normArray.length / 3,
                getX: (i) => normArray[i * 3],
                getY: (i) => normArray[i * 3 + 1],
                getZ: (i) => normArray[i * 3 + 2]
            }
        },
        index: {
            count: idxArray.length,
            getX: (i) => idxArray[i]
        }
    };
}

function createCylinderBufferGeometry(radiusTop, radiusBottom, height, segments) {
    const positions = [];
    const normals = [];
    const indices = [];

    const halfHeight = height / 2;

    // Side vertices
    for (let i = 0; i <= segments; i++) {
        const theta = (i / segments) * Math.PI * 2;
        const cos = Math.cos(theta);
        const sin = Math.sin(theta);

        for (let y = 0; y <= 1; y++) {
            const r = y === 0 ? radiusBottom : radiusTop;
            positions.push(cos * r, (y - 0.5) * height, sin * r);
            normals.push(cos, 0, sin);
        }
    }

    // Side indices
    for (let i = 0; i < segments; i++) {
        const a = i * 2;
        const b = a + 1;
        const c = a + 2;
        const d = a + 3;
        indices.push(a, b, c, b, d, c);
    }

    // Top cap
    const topCenterIndex = positions.length / 3;
    positions.push(0, halfHeight, 0);
    normals.push(0, 1, 0);

    for (let i = 0; i <= segments; i++) {
        const theta = (i / segments) * Math.PI * 2;
        const cos = Math.cos(theta);
        const sin = Math.sin(theta);
        positions.push(cos * radiusTop, halfHeight, sin * radiusTop);
        normals.push(0, 1, 0);
    }

    for (let i = 0; i < segments; i++) {
        indices.push(topCenterIndex, topCenterIndex + i + 1, topCenterIndex + i + 2);
    }

    // Bottom cap
    const bottomCenterIndex = positions.length / 3;
    positions.push(0, -halfHeight, 0);
    normals.push(0, -1, 0);

    for (let i = 0; i <= segments; i++) {
        const theta = (i / segments) * Math.PI * 2;
        const cos = Math.cos(theta);
        const sin = Math.sin(theta);
        positions.push(cos * radiusBottom, -halfHeight, sin * radiusBottom);
        normals.push(0, -1, 0);
    }

    for (let i = 0; i < segments; i++) {
        indices.push(bottomCenterIndex, bottomCenterIndex + i + 2, bottomCenterIndex + i + 1);
    }

    return {
        attributes: {
            position: {
                count: positions.length / 3,
                getX: (i) => positions[i * 3],
                getY: (i) => positions[i * 3 + 1],
                getZ: (i) => positions[i * 3 + 2]
            },
            normal: {
                count: normals.length / 3,
                getX: (i) => normals[i * 3],
                getY: (i) => normals[i * 3 + 1],
                getZ: (i) => normals[i * 3 + 2]
            }
        },
        index: {
            count: indices.length,
            getX: (i) => indices[i]
        }
    };
}

function createTorusBufferGeometry(radius, tube, radialSegments, tubularSegments) {
    const positions = [];
    const normals = [];
    const indices = [];

    for (let j = 0; j <= radialSegments; j++) {
        for (let i = 0; i <= tubularSegments; i++) {
            const u = (i / tubularSegments) * Math.PI * 2;
            const v = (j / radialSegments) * Math.PI * 2;

            const centerX = radius * Math.cos(u);
            const centerY = radius * Math.sin(u);

            const x = (radius + tube * Math.cos(v)) * Math.cos(u);
            const y = (radius + tube * Math.cos(v)) * Math.sin(u);
            const z = tube * Math.sin(v);

            positions.push(x, y, z);
            normals.push(Math.cos(v) * Math.cos(u), Math.cos(v) * Math.sin(u), Math.sin(v));
        }
    }

    for (let j = 0; j < radialSegments; j++) {
        for (let i = 0; i < tubularSegments; i++) {
            const a = (tubularSegments + 1) * j + i;
            const b = (tubularSegments + 1) * (j + 1) + i;
            const c = (tubularSegments + 1) * (j + 1) + i + 1;
            const d = (tubularSegments + 1) * j + i + 1;

            indices.push(a, b, d);
            indices.push(b, c, d);
        }
    }

    return {
        attributes: {
            position: {
                count: positions.length / 3,
                getX: (i) => positions[i * 3],
                getY: (i) => positions[i * 3 + 1],
                getZ: (i) => positions[i * 3 + 2]
            },
            normal: {
                count: normals.length / 3,
                getX: (i) => normals[i * 3],
                getY: (i) => normals[i * 3 + 1],
                getZ: (i) => normals[i * 3 + 2]
            }
        },
        index: {
            count: indices.length,
            getX: (i) => indices[i]
        }
    };
}

function createConeBufferGeometry(radius, height, segments) {
    const positions = [];
    const normals = [];
    const indices = [];

    const halfHeight = height / 2;

    // Side vertices
    for (let i = 0; i <= segments; i++) {
        const theta = (i / segments) * Math.PI * 2;
        const cos = Math.cos(theta);
        const sin = Math.sin(theta);

        // Tip vertex
        if (i === 0) {
            positions.push(0, halfHeight, 0);
            const slope = radius / height;
            const normalLen = 1 / Math.sqrt(1 + slope * slope);
            normals.push(cos * normalLen, slope * normalLen, sin * normalLen);
        }

        // Base vertices
        positions.push(cos * radius, -halfHeight, sin * radius);
        normals.push(cos, 0.3, sin); // Approximate normal
    }

    // Close the base
    positions.push(0, -halfHeight, 0);
    normals.push(0, -1, 0);

    // Side indices
    for (let i = 0; i < segments; i++) {
        indices.push(0, i + 1, i + 2);
    }

    // Base indices
    const baseStart = positions.length / 3 - 1;
    for (let i = 0; i < segments; i++) {
        indices.push(baseStart, baseStart + i + 2, baseStart + i + 1);
    }

    return {
        attributes: {
            position: {
                count: positions.length / 3,
                getX: (i) => positions[i * 3],
                getY: (i) => positions[i * 3 + 1],
                getZ: (i) => positions[i * 3 + 2]
            },
            normal: {
                count: normals.length / 3,
                getX: (i) => normals[i * 3],
                getY: (i) => normals[i * 3 + 1],
                getZ: (i) => normals[i * 3 + 2]
            }
        },
        index: {
            count: indices.length,
            getX: (i) => indices[i]
        }
    };
}

function createCylinderBeamBufferGeometry(length, radius, segments) {
    return createCylinderBufferGeometry(radius, radius, length, segments);
}

