        const cos = Math.cos(theta);
        const sin = Math.sin(theta);

        // Tip vertex
        if (i === 0) {
            positions.push(0, halfHeight, 0);
            const slope = radius / height;
            const normalLen = 1 / Math.sqrt(1 + slope * slope);
            normals.push(cos * normalLen, slope * normalLen, sin * normalLen);
        }

        // Base vertices
        positions.push(cos * radius, -halfHeight, sin * radius);
        normals.push(cos, 0.3, sin); // Approximate normal
    }

    // Close the base
    positions.push(0, -halfHeight, 0);
    normals.push(0, -1, 0);

    // Side indices
    for (let i = 0; i < segments; i++) {
        indices.push(0, i + 1, i + 2);
